CREATE TABLE group_batches(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,owner_customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL,label TEXT NOT NULL,branch_id TEXT NOT NULL REFERENCES branches(id),max_members INTEGER NOT NULL CHECK(max_members BETWEEN 2 AND 20),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,closed INTEGER NOT NULL DEFAULT 0);
ALTER TABLE orders ADD COLUMN group_id TEXT REFERENCES group_batches(id) ON DELETE SET NULL;
CREATE UNIQUE INDEX group_one_active_order ON orders(group_id,customer_id) WHERE group_id IS NOT NULL AND customer_id IS NOT NULL AND status!='cancelled';
CREATE TRIGGER royal_group_capacity BEFORE INSERT ON orders WHEN NEW.group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.id) BEGIN SELECT CASE WHEN NEW.customer_id IS NULL THEN RAISE(ABORT,'group_account') END; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM group_batches WHERE id=NEW.group_id AND branch_id=NEW.branch_id AND closed=0 AND expires_at>CAST(strftime('%s','now') AS INTEGER)) THEN RAISE(ABORT,'group_closed') END; SELECT CASE WHEN (SELECT COUNT(*) FROM orders WHERE group_id=NEW.group_id AND status!='cancelled')>=(SELECT max_members FROM group_batches WHERE id=NEW.group_id) THEN RAISE(ABORT,'group_full') END; END;
